import os


def get():
    if os.path.isdir('/opt/cus'):
        return 'cus'
    elif os.path.isdir('/opt/rtg'):
        return 'rtg'
    else:
        raise EnvironmentError("Neither '/opt/cus' nor '/opt/rtg' was found. Please install RTG/CUS package before using ta_ue_plugin_rtg")
